CREATE TABLE IF NOT EXISTS platform_accounts(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),platform TEXT NOT NULL,account_name TEXT,external_account_ref TEXT,state TEXT NOT NULL DEFAULT 'DISCONNECTED',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS platform_connections(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),platform TEXT NOT NULL,platform_account_id TEXT REFERENCES platform_accounts(id),state TEXT NOT NULL,capabilities_json TEXT NOT NULL DEFAULT '[]',scopes_json TEXT NOT NULL DEFAULT '[]',token_ref TEXT,token_expires_at TEXT,last_probe_at TEXT,limitations_json TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS brand_profiles(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),brand_name TEXT NOT NULL,audience TEXT NOT NULL,voice TEXT NOT NULL,tone TEXT NOT NULL,do_rules_json TEXT NOT NULL DEFAULT '[]',dont_rules_json TEXT NOT NULL DEFAULT '[]',visual_rules_json TEXT NOT NULL DEFAULT '[]',cta_rules_json TEXT NOT NULL DEFAULT '[]',claim_rules_json TEXT NOT NULL DEFAULT '[]',platform_rules_json TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS prompt_templates(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),template_id TEXT NOT NULL,version TEXT NOT NULL,template_text TEXT NOT NULL,variables_hash TEXT NOT NULL,rendered_prompt_hash TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(workspace_id,template_id,version));
CREATE TABLE IF NOT EXISTS publication_evidence(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),content_id TEXT NOT NULL REFERENCES content_items(id),platform TEXT NOT NULL,provider TEXT,status TEXT NOT NULL,evidence_ref TEXT,provider_post_id TEXT,confirmed_by TEXT,confirmed_at TEXT,request_id TEXT,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_platform_accounts_workspace ON platform_accounts(workspace_id,platform);
CREATE INDEX IF NOT EXISTS idx_platform_connections_workspace ON platform_connections(workspace_id,platform,state);
CREATE INDEX IF NOT EXISTS idx_brand_profiles_workspace ON brand_profiles(workspace_id);
CREATE INDEX IF NOT EXISTS idx_prompt_templates_workspace ON prompt_templates(workspace_id,template_id,version);
CREATE INDEX IF NOT EXISTS idx_publication_evidence_content ON publication_evidence(workspace_id,content_id,platform);
